INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$8e2e424e$SATQ$, NULL, NULL, $SATQ$031617-DC$SATQ$, $SATQ$disclosed$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Problem-Solving and Data Analysis$SATQ$, $SATQ$Q$SATQ$, $SATQ$Q.B.$SATQ$, $SATQ$Percentages$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, NULL, $SATQ$<p class="stem_paragraph ">The number <span class="italic">k</span> is 36% greater than 50. If <span class="italic">k</span> is the product of 50 and <span class="italic">r</span>, what is the value of <span class="italic">r&nbsp;</span>?</p>
$SATQ$, $SATQ$[{"id":"a","content":"<p class=\"choice_paragraph \">36</p>\n"},{"id":"b","content":"<p class=\"choice_paragraph \">3.6</p>\n"},{"id":"c","content":"<p class=\"choice_paragraph \">1.36</p>\n"},{"id":"d","content":"<p class=\"choice_paragraph \">0.36</p>\n"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, NULL, $SATQ$<p>Choice C is correct. It&rsquo;s given that the number <span class="italic">k</span> is 36% greater than 50. Therefore, the value of <span class="italic">k</span> is the number 50 plus 36% of 50. This can be rewritten as <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_000_53988649.png" alt="k equals, 50 plus, the fraction 36 over 100, end fraction, times 50"></span>. Multiplying the terms <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_001_5e9d3c97.png" alt="the fraction 36 over 100, end fraction, times 50"></span> yields 18, so <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_002_fabab4d3.png" alt="k equals, 50 plus 18"></span>, or <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_003_fc0a9fe7.png" alt="k equals 68"></span>. It&rsquo;s also given that <span class="italic">k</span> is the product of 50 and <span class="italic">r</span>, which can be rewritten as <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_004_be4f177a.png" alt="k equals 50 r"></span>. Substituting 68 for <span class="italic">k</span> yields <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_005_65480a16.png" alt="68 equals 50 r"></span>. Dividing both sides of this equation by 50 yields <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_006_2e59d36f.png" alt="r equals 1 point 3 6"></span>.<p>Choice A is incorrect. This is the percentage that <span class="italic">k</span> is greater than 50. Choice B is incorrect and may result from a calculation error. Choice D is incorrect. This would be the value of <span class="italic">r</span> if <span class="italic">k</span> were 36% of 50, instead of 36% greater than 50.</p><p>&nbsp;</p></p>
$SATQ$, false, 7, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ$Multiple Choice$SATQ$, $SATQ$Math$SATQ$, $SATQ${"questionId":"8e2e424e","external_id":null,"disclosed_item_id":"031617-DC","source":"disclosed","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"Q","domain":"Problem-Solving and Data Analysis","skill_cd":"Q.B.","skill_desc":"Percentages","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":null,"stem":"<p class=\"stem_paragraph \">The number <span class=\"italic\">k</span> is 36% greater than 50. If <span class=\"italic\">k</span> is the product of 50 and <span class=\"italic\">r</span>, what is the value of <span class=\"italic\">r&nbsp;</span>?</p>\n","answerOptions":[{"id":"a","content":"<p class=\"choice_paragraph \">36</p>\n"},{"id":"b","content":"<p class=\"choice_paragraph \">3.6</p>\n"},{"id":"c","content":"<p class=\"choice_paragraph \">1.36</p>\n"},{"id":"d","content":"<p class=\"choice_paragraph \">0.36</p>\n"}],"keys":null,"correct_answer":["C"],"rationale":"<p>Choice C is correct. It&rsquo;s given that the number <span class=\"italic\">k</span> is 36% greater than 50. Therefore, the value of <span class=\"italic\">k</span> is the number 50 plus 36% of 50. This can be rewritten as <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_000_53988649.png\" alt=\"k equals, 50 plus, the fraction 36 over 100, end fraction, times 50\"></span>. Multiplying the terms <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_001_5e9d3c97.png\" alt=\"the fraction 36 over 100, end fraction, times 50\"></span> yields 18, so <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_002_fabab4d3.png\" alt=\"k equals, 50 plus 18\"></span>, or <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_003_fc0a9fe7.png\" alt=\"k equals 68\"></span>. It&rsquo;s also given that <span class=\"italic\">k</span> is the product of 50 and <span class=\"italic\">r</span>, which can be rewritten as <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_004_be4f177a.png\" alt=\"k equals 50 r\"></span>. Substituting 68 for <span class=\"italic\">k</span> yields <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_005_65480a16.png\" alt=\"68 equals 50 r\"></span>. Dividing both sides of this equation by 50 yields <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e2e424e/img_006_2e59d36f.png\" alt=\"r equals 1 point 3 6\"></span>.<p>Choice A is incorrect. This is the percentage that <span class=\"italic\">k</span> is greater than 50. Choice B is incorrect and may result from a calculation error. Choice D is incorrect. This would be the value of <span class=\"italic\">r</span> if <span class=\"italic\">k</span> were 36% of 50, instead of 36% greater than 50.</p><p>&nbsp;</p></p>\n","answer_style":"Multiple Choice","section":"Math","image_count":7,"raw_list":{"updateDate":1691007959626,"pPcc":"SAT#Q","questionId":"8e2e424e","skill_cd":"Q.B.","score_band_range_cd":4,"skill_desc":"Percentages","createDate":1691007959626,"program":"SAT","primary_class_cd_desc":"Problem-Solving and Data Analysis","ibn":"031617-DC","external_id":null,"primary_class_cd":"Q","uId":"601435b2-93df-4fc6-a3d8-d4226f79fc0d","difficulty":"M"},"raw_detail":{"item_id":"031617-DC","section":"Math","prompt":"<p class=\"stem_paragraph \">The number <span class=\"italic\">k</span> is 36% greater than 50. If <span class=\"italic\">k</span> is the product of 50 and <span class=\"italic\">r</span>, what is the value of <span class=\"italic\">r&nbsp;</span>?</p>\n","answer":{"style":"Multiple Choice","choices":{"a":{"body":"<p class=\"choice_paragraph \">36</p>\n"},"b":{"body":"<p class=\"choice_paragraph \">3.6</p>\n"},"c":{"body":"<p class=\"choice_paragraph \">1.36</p>\n"},"d":{"body":"<p class=\"choice_paragraph \">0.36</p>\n"}},"correct_choice":"c","rationale":"<p>Choice C is correct. It&rsquo;s given that the number <span class=\"italic\">k</span> is 36% greater than 50. Therefore, the value of <span class=\"italic\">k</span> is the number 50 plus 36% of 50. This can be rewritten as <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k equals, 50 plus, the fraction 36 over 100, end fraction, times 50\"></span>. Multiplying the terms <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"the fraction 36 over 100, end fraction, times 50\"></span> yields 18, so <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k equals, 50 plus 18\"></span>, or <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k equals 68\"></span>. It&rsquo;s also given that <span class=\"italic\">k</span> is the product of 50 and <span class=\"italic\">r</span>, which can be rewritten as <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k equals 50 r\"></span>. Substituting 68 for <span class=\"italic\">k</span> yields <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"68 equals 50 r\"></span>. Dividing both sides of this equation by 50 yields <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"r equals 1 point 3 6\"></span>.<p>Choice A is incorrect. This is the percentage that <span class=\"italic\">k</span> is greater than 50. Choice B is incorrect and may result from a calculation error. Choice D is incorrect. This would be the value of <span class=\"italic\">r</span> if <span class=\"italic\">k</span> were 36% of 50, instead of 36% greater than 50.</p><p>&nbsp;</p></p>\n"}},"createDate":1691007959626,"updateDate":1691007959626}$SATQ$::jsonb, 1691007959626, 1691007959626),
    ($SATQ$8e528129$SATQ$, NULL, NULL, $SATQ$070608-DC$SATQ$, $SATQ$disclosed$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Problem-Solving and Data Analysis$SATQ$, $SATQ$Q$SATQ$, $SATQ$Q.A.$SATQ$, $SATQ$Ratios, rates, proportional relationships, and units$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$spr$SATQ$, NULL, $SATQ$<p class="stem_paragraph ">Pure beeswax has a density of 0.555 ounce per cubic inch. An online company sells pure beeswax at a price of $8.00 per ounce. What is the selling price, in dollars per cubic inch, for pure beeswax purchased from this company?</p>
$SATQ$, NULL, $SATQ$["4.44"]$SATQ$::jsonb, NULL, $SATQ$<p>The correct answer is 4.44. The selling price, in dollars per cubic inch, is found by multiplying the density, in ounces per cubic inch, by the unit price, in dollars per ounce: <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e528129/img_000_19d6acc8.png" alt="open parenthesis, 0 point 5 5 5 ounce, over 1 cubic inch, close parenthesis, times, open parenthesis, 8 dollars, over 1 ounce, close parenthesis "></span> yields <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e528129/img_001_8b69d3f1.png" alt="4 point 4 4 dollars over 1 cubic inch "></span>. Thus, the selling price, in dollars per cubic inch, is 4.44.</p>
$SATQ$, true, 2, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ$SPR$SATQ$, $SATQ$Math$SATQ$, $SATQ${"questionId":"8e528129","external_id":null,"disclosed_item_id":"070608-DC","source":"disclosed","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"Q","domain":"Problem-Solving and Data Analysis","skill_cd":"Q.A.","skill_desc":"Ratios, rates, proportional relationships, and units","difficulty":"M","score_band_range_cd":5,"type":"spr","stimulus":null,"stem":"<p class=\"stem_paragraph \">Pure beeswax has a density of 0.555 ounce per cubic inch. An online company sells pure beeswax at a price of $8.00 per ounce. What is the selling price, in dollars per cubic inch, for pure beeswax purchased from this company?</p>\n","answerOptions":null,"keys":null,"correct_answer":["4.44"],"rationale":"<p>The correct answer is 4.44. The selling price, in dollars per cubic inch, is found by multiplying the density, in ounces per cubic inch, by the unit price, in dollars per ounce: <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e528129/img_000_19d6acc8.png\" alt=\"open parenthesis, 0 point 5 5 5 ounce, over 1 cubic inch, close parenthesis, times, open parenthesis, 8 dollars, over 1 ounce, close parenthesis \"></span> yields <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/8e528129/img_001_8b69d3f1.png\" alt=\"4 point 4 4 dollars over 1 cubic inch \"></span>. Thus, the selling price, in dollars per cubic inch, is 4.44.</p>\n","answer_style":"SPR","section":"Math","image_count":2,"raw_list":{"updateDate":1691007959631,"pPcc":"SAT#Q","questionId":"8e528129","skill_cd":"Q.A.","score_band_range_cd":5,"skill_desc":"Ratios, rates, proportional relationships, and units","createDate":1691007959631,"program":"SAT","primary_class_cd_desc":"Pro